using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
internal sealed class WallpaperCard:Control {
 internal readonly WallpaperItem Item;internal bool Selected,Active;internal string Compatibility;Image cover;bool hover,pressed;float hoverLift;readonly Timer hoverTimer=new Timer{Interval=16};readonly System.Diagnostics.Stopwatch hoverClock=new System.Diagnostics.Stopwatch();float hoverStart,hoverTarget;internal event EventHandler Chosen;
 internal WallpaperCard(WallpaperItem item,string compatibility){Item=item;Compatibility=compatibility;cover=WallpaperLibrary.LoadCover(item);Size=new Size(300,260);Margin=new Padding(0,0,18,18);DoubleBuffered=true;Cursor=Cursors.Hand;TabStop=true;AccessibleName=item.Name;AccessibleRole=AccessibleRole.PushButton;hoverTimer.Tick+=(s,e)=>{float t=Math.Min(1,hoverClock.ElapsedMilliseconds/240f);hoverLift=hoverStart+(hoverTarget-hoverStart)*(1-(float)Math.Pow(1-t,3));Invalidate();if(t>=1)hoverTimer.Stop();};}
 protected override void OnClick(EventArgs e){base.OnClick(e);Focus();if(Chosen!=null)Chosen(this,e);}protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Space||e.KeyCode==Keys.Enter)OnClick(EventArgs.Empty);}
 void AnimateHover(bool entered){hoverStart=hoverLift;hoverTarget=entered&&SoftButton.MotionEnabled?4:0;hoverClock.Restart();if(SoftButton.MotionEnabled)hoverTimer.Start();else{hoverLift=0;hoverTimer.Stop();}}
