  var imageBounds=new Rectangle(pad,pad,Width-pad*2,Height-titleH-noteH-pad*3-6);using(var path=Theme.Round(imageBounds,8)){using(var old=g.Clip){g.SetClip(path);if(cover!=null){double scale=Math.Max((double)imageBounds.Width/cover.Width,(double)imageBounds.Height/cover.Height);float w=(float)(cover.Width*scale),h=(float)(cover.Height*scale);g.DrawImage(cover,imageBounds.X+(imageBounds.Width-w)/2,imageBounds.Y+(imageBounds.Height-h)/2,w,h);}else{using(var b=new SolidBrush(Color.FromArgb(237,239,243)))g.FillRectangle(b,imageBounds);TextRenderer.DrawText(g,VideoPackage.Extension(Item.SourcePath)?"视频壁纸 · 暂无封面":"暂无封面",Font,imageBounds,Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}g.Clip=old;}}
  using(var title=new Font(Font.FontFamily,10.5f,FontStyle.Bold))TextRenderer.DrawText(g,Item.Name,title,new Rectangle(pad+5,imageBounds.Bottom+pad,Width-pad*2-10,titleH),Theme.Ink,TextFormatFlags.NoPrefix|TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine);Color color=Compatibility=="已验证"||Compatibility.StartsWith("窗口已确认")?Color.FromArgb(37,126,101):Compatibility=="文件不存在"?Color.FromArgb(181,58,51):Theme.Muted;TextRenderer.DrawText(g,Compatibility=="窗口画面已确认"?"预览已确认":Compatibility,Font,new Rectangle(pad+5,imageBounds.Bottom+pad+titleH,Width-pad*2-10,noteH),color,TextFormatFlags.Left|TextFormatFlags.SingleLine);
  if(Active){var b=new Rectangle(pad+7,pad+7,(int)(76*k),(int)(25*k));using(var path=Theme.Round(b,8)){using(var brush=new SolidBrush(Color.FromArgb(239,248,244)))g.FillPath(brush,path);}using(var f=new Font(Font.FontFamily,8.5f,FontStyle.Bold))TextRenderer.DrawText(g,"正在使用",f,b,Color.FromArgb(30,111,79),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}if(Selected){int size=(int)(21*k);var dot=new Rectangle(Width-pad-size-7,pad+7,size,size);using(var b=new SolidBrush(Theme.Blue))g.FillEllipse(b,dot);TextRenderer.DrawText(g,"✓",Font,dot,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(6,6,Width-13,Height-15));
 }
